class Solution:
    def minMeetingRooms(self, intervals: List[List[int]]) -> int:
        intervals.sort(key=lambda iv: iv[0])
        busy_until = []   # min-heap of end times of meetings occupying a room
        rooms = 0
        for start, end in intervals:
            if busy_until and busy_until[0] <= start:
                heapq.heapreplace(busy_until, end)   # reuse the room that frees up earliest
            else:
                heapq.heappush(busy_until, end)      # need a new room
            rooms = max(rooms, len(busy_until))
        return rooms

